package com.eventdrivencommerce.order.api;
import com.eventdrivencommerce.order.application.model.CreateOrderResult;import com.eventdrivencommerce.order.application.port.in.OrderUseCase;import com.eventdrivencommerce.order.domain.model.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.when;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(OrderController.class) class OrderControllerTest {
 @Autowired MockMvc mvc;@MockitoBean OrderUseCase orders;@MockitoBean OrderStatusStream stream;
 @Test void createsAcceptedOrderWithLocationAndCorrelation()throws Exception{var a=new Address("Name","Street","","123","City","SE");var o=Order.create(UUID.randomUUID(),List.of(OrderLine.priced(UUID.randomUUID(),"SKU","Product",2,new BigDecimal("10"))),"SEK",a,a,"key","fp",Instant.parse("2026-01-01T00:00:00Z"));when(orders.create(any())).thenReturn(new CreateOrderResult(o,false));String body="{\"lines\":[{\"productId\":\"%s\",\"quantity\":2}],\"currency\":\"SEK\",\"shippingAddress\":{\"recipient\":\"Name\",\"line1\":\"Street\",\"postalCode\":\"123\",\"city\":\"City\",\"countryCode\":\"SE\"},\"billingAddress\":{\"recipient\":\"Name\",\"line1\":\"Street\",\"postalCode\":\"123\",\"city\":\"City\",\"countryCode\":\"SE\"}}".formatted(o.lines().getFirst().productId());mvc.perform(post("/api/v1/orders").header("X-Customer-ID",o.customerId()).header("Idempotency-Key","key").contentType("application/json").content(body)).andExpect(status().isAccepted()).andExpect(header().string("Location","/api/v1/orders/"+o.id())).andExpect(header().exists("X-Correlation-ID")).andExpect(jsonPath("$.status").value("PENDING"));}
}
